import { notFound } from "next/navigation"

const pages: Record<string, { title: string; note: string }> = {
  "": { title: "Dashboard Overview", note: "Starter entry route under /template." },
  "dashboard": { title: "Dashboard Overview", note: "Cards and charts overview page." },
  "dashboard/product": { title: "Product List", note: "Table page with filters and pagination in the original template." },
  "dashboard/product/new": { title: "Create Product", note: "Create product form route." },
  "dashboard/users": { title: "Users", note: "Users table route." },
  "dashboard/react-query": { title: "React Query Demo", note: "Server prefetch + hydrated client data route." },
  "dashboard/profile": { title: "Profile", note: "User profile management route." },
  "dashboard/kanban": { title: "Kanban", note: "Drag-and-drop board route." },
  "dashboard/chat": { title: "Chat", note: "Messaging UI route." },
  "dashboard/ai-chat": { title: "AI Chat", note: "Scripted AI chat route." },
  "dashboard/notifications": { title: "Notifications", note: "Notification center route." },
  "dashboard/workspaces": { title: "Workspaces", note: "Organization/workspace management route." },
  "dashboard/workspaces/team": { title: "Team Management", note: "Workspace team management route." },
  "dashboard/billing": { title: "Billing & Plans", note: "Billing and pricing route." },
  "dashboard/exclusive": { title: "Exclusive", note: "Plan-gated feature route." },
  "dashboard/notfound": { title: "Not Found", note: "Not found sample route." },
  "auth/sign-in": { title: "Sign In", note: "Authentication sign-in route." },
  "auth/sign-up": { title: "Sign Up", note: "Authentication sign-up route." },
}

export default function TemplatePage({ params }: { params: { slug?: string[] } }) {
  const key = (params.slug ?? []).join("/")
  const page = pages[key]

  if (!page) {
    notFound()
  }

  return (
    <main className="p-6">
      <section className="rounded-xl border border-zinc-200 bg-white p-6">
        <h1 className="text-2xl font-semibold text-zinc-900">{page.title}</h1>
        <p className="mt-2 text-zinc-600">{page.note}</p>
        <p className="mt-6 text-sm text-zinc-500">
          Route: /template{key ? `/${key}` : ""}
        </p>
      </section>
    </main>
  )
}
